const inicio = Date.now();
const fonte = $json.fonte;
const versaoApi = 'v2';
const base = 'https://www.googleapis.com/tagmanager/v2';
const publicId = String(fonte.externalId);
let requests = 0;
let bytes = 0;

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - inicio },
      falhas,
      requests,
      versaoApi,
    },
  }];
}

async function buscar(url) {
  requests += 1;
  const resposta = await this.helpers.httpRequestWithAuthentication.call(this, 'googleOAuth2Api', {
    method: 'GET',
    url,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  bytes += JSON.stringify(resposta.body ?? {}).length;
  return resposta;
}

function falhaHttp(resposta) {
  const detalhe = resposta.body?.error?.message || `HTTP ${resposta.statusCode}`;
  const causa = resposta.statusCode === 401 || resposta.statusCode === 403 ? 'reauth_pending' : 'api_recusou';
  return [{ causa, detalhe }];
}

try {
  const contas = await buscar.call(this, `${base}/accounts`);
  if (contas.statusCode < 200 || contas.statusCode >= 300) return devolver([], falhaHttp(contas));

  let container = null;
  for (const conta of contas.body?.account ?? []) {
    const lista = await buscar.call(this, `${base}/${conta.path}/containers`);
    if (lista.statusCode < 200 || lista.statusCode >= 300) return devolver([], falhaHttp(lista));
    container = (lista.body?.container ?? []).find((item) => item.publicId === publicId) ?? null;
    if (container) break;
  }

  if (!container) {
    return devolver([], [{ causa: 'fonte_nao_encontrada', detalhe: `contêiner ${publicId} não aparece para esta credencial` }]);
  }

  const live = await buscar.call(this, `${base}/${container.path}/versions:live`);
  const publicada = live.statusCode >= 200 && live.statusCode < 300 ? live.body : null;
  if (!publicada && live.statusCode !== 404) return devolver([], falhaHttp(live));

  const estado = publicada
    ? `live v${publicada.containerVersionId} · ${(publicada.tag ?? []).length} tags · ${(publicada.trigger ?? []).length} acionadores · ${(publicada.variable ?? []).length} variáveis`
    : 'sem_versao_publicada';

  return devolver([{
    nome: container.name,
    estado,
    inactive: false,
    rotuloEsperado: fonte.nome ?? null,
    rotuloObservado: container.name,
  }], []);
} catch (erro) {
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${erro.message}` }]);
}
